style.css:
@-moz-document domain("websudoku.com") {
/* الخلفية العامة للموقع */
    html, body, frameset, frame {
        background-color: #0f0f11 !important;
        background: #0f0f11 !important;
        color: #e4e4e7 !important;
    }

    body {
        margin: 0;
        font-family: 'Segoe UI', Roboto, Arial, sans-serif !important;
        color: #d4d4d8 !important;
    }

    table {
        background-color: transparent !important;
    }
    
    td {
        color: #d4d4d8 !important;
    }

    /* الشريط الجانبي الأيسر */
    #left-column {
        background-color: #18181b !important;
        border-right: 1px solid #27272a !important;
    }

    .left-bordered {
        border-right: 1px #27272a solid !important;
    }

    /* خلايا شبكة السودوكو */
    td.c0, td.c1, td.c2, td.c3,
    td.e0, td.e1, td.e2, td.e3,
    td.f0, td.f1, td.f2, td.f3,
    td.g0, td.g1, td.g2, td.g3,
    td.h0, td.h1, td.h2, td.h3,
    td.i0, td.i1, td.i2, td.i3 {
        background-color: #1c1c1f !important;
        border-color: #3f3f46 !important;
    }

    /* حقول الإدخال */
    input.d0, input.d1, input.d2, input.d3,
    input.s0, input.s1, input.s2, input.s3,
    input.u0, input.u1, input.u2, input.u3,
    input.w0, input.w1, input.w2, input.w3,
    input.v0, input.v1, input.v2, input.v3 {
        background-color: transparent !important;
        color: #e4e4e7 !important;
        border: none !important;
        outline: none !important;
        transition: background-color 0.2s, box-shadow 0.2s;
    }

    /* الأرقام الأساسية الجاهزة (المعطيات) */
    input.s0, input.s1, input.s2, input.s3,
    input.u0, input.u1, input.u2, input.u3 {
        color: #ffffff !important;
        font-weight: bold !important;
        background-color: #27272a !important;
    }

    /* الأرقام التي يقوم اللاعب بإدخالها */
    input.d0, input.d2, input.d3 {
        color: #60a5fa !important; /* لون أزرق مريح للعين */
    }

    /* عند تحديد الخلية للإدخال */
    input.d0:focus, input.s0:focus, input:focus {
        background-color: #2e2e38 !important;
        box-shadow: inset 0 0 0 2px #3b82f6 !important;
    }

    /* إبراز الأخطاء باللون الأحمر */
    .c1, .c2, .c3,
    .d1, .d2, .d3,
    .e1, .e2, .e3,
    .f1, .f2, .f3,
    .g1, .g2, .g3,
    .h1, .h2, .h3,
    .i1, .i2, .i3 {
        background-color: #450a0a !important;
        color: #ef4444 !important;
    }

    /* الروابط والأزرار */
    a:link, a:visited, a:active {
        color: #60a5fa !important;
    }

    a:hover {
        color: #93c5fd !important;
        text-decoration: underline !important;
    }

    #logo img {
        filter: invert(0.9) hue-rotate(180deg) !important;
        opacity: 0.8;
    }

    input[type="submit"], input[type="button"], input.reset, button {
        background-color: #27272a !important;
        color: #f4f4f5 !important;
        border: 1px solid #3f3f46 !important;
        border-radius: 6px !important;
        padding: 6px 12px !important;
        cursor: pointer !important;
    }

    input[type="submit"]:hover, input[type="button"]:hover, button:hover {
        background-color: #3f3f46 !important;
    }
}
